#include <iostream>
#include <string>

using namespace std;

bool isUpper(char c) {
    return c >= 'A' && c <= 'Z';
}

bool isDigit(char c) {
    return c >= '0' && c <= '9';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!(cin >> s)) return 0;

    if (s.length() == 8) {
        if (isUpper(s[0]) && isUpper(s[1]) && isUpper(s[2]) &&
            s[3] == '-' &&
            isDigit(s[4]) && isDigit(s[5]) && isDigit(s[6]) && isDigit(s[7])) {
            cout << 1 << "\n";
            return 0;
        }
    } else if (s.length() == 7) {
        if (isUpper(s[0]) && isUpper(s[1]) && isUpper(s[2]) &&
            isDigit(s[3]) &&
            isUpper(s[4]) &&
            isDigit(s[5]) && isDigit(s[6])) {
            cout << 2 << "\n";
            return 0;
        }
    }

    cout << 0 << "\n";
    return 0;
}
